"""Write plain-language D3 notes for the eighteenth full-paper reading pass."""
import json
from pathlib import Path
H=Path(__file__).resolve().parent; D=H/"data"; R=H/"reports"
C={x["paper_id"]:x for x in json.loads((D/"interspeech-2025-eighteenth-d3-papers.json").read_text())["papers"]}
P={x["paper_id"]:x for x in json.loads((D/"interspeech-2025-papers.json").read_text())["papers"]}
N={
"du25c_interspeech":("Clinicians must distinguish two voice disorders from patients' speech, but expert listening is scarce and subjective.","The disorders can sound similar and their acoustic signs vary across patients.","Rely only on a clinician's global impression or on generic acoustic features.","Combine expert-designed voice measures with representations learned directly from the waveform.","A CNN receives handcrafted features and self-supervised waveform representations and predicts ADSD versus pMTD on a newly collected patient dataset.","The decision is a two-class prediction; accuracy measures the fraction of correctly classified patients.","The paper reports 83.3% classification accuracy.","The result is tied to the constructed dataset, its patient mix, and the two diagnoses; clinical deployment, calibration, and external validation remain open."),
"ankita25_interspeech":("A child ASR system must recognize speech when only a small amount of child data is available.","Children's voices differ from adults and scarce data makes both acoustic modeling and pronunciation variation difficult.","Train a standard spectrum-only ASR model and accept its data-scarcity error.","Augment in-domain data, add glottal-activity information to spectral features, and normalize features with fMLLR.","The study compares a baseline with augmented data, MFCCs plus glottal parameters, and fMLLR-normalized features.","Character error rate is the main error measure; relative reduction compares each system with the baseline.","The combined normalized MFCC and glottal features give a reported 40% relative character-error-rate reduction over baseline.","The evidence is limited to the child's speech data and tested feature pipeline; languages, age ranges, and transfer to new schools or microphones are not established."),
"hartanto25_interspeech":("A separator must recover each speaker while also coping with where speakers and microphones sit in a reverberant room.","Noise and reverberation can make room effects look like properties of the speech itself.","Ask one network to separate speech while treating the room and microphone arrangement as irrelevant nuisance.","Predict speech separation and the physical recording conditions together, then use curriculum learning to stabilize training.","SepVAC jointly estimates separated speech, speaker locations, microphone-array location, and room acoustic parameters on SMS-WSJ-Plus.","Word error rate evaluates the usefulness of the separated signal to recognition; the multitask losses constrain both speech and scene estimates.","The paper reports a 0.67-point WER improvement over SpatialNet.","The result is author-reported on SMS-WSJ-Plus and its simulated acoustic conditions; real rooms, imperfect localization, and independent reproduction remain open."),
"dasilva25_interspeech":("In a group conversation, a listener's brain activity can indicate which talker they are attending to; the system should recover that talker's speech.","The neural cue is noisy and the extracted waveform can sound plausible while still losing the speech envelope that carries intelligibility.","Optimize only waveform reconstruction and hope the attended speaker remains identifiable.","Train the extractor on two linked targets: the target waveform and its amplitude envelope.","NeuroSpex+ uses EEG-derived reference cues and jointly predicts the target waveform and speech envelope to shape its mask.","The two reconstruction objectives constrain both detailed waveform quality and slower envelope structure; signal-quality measures compare with baselines.","The paper reports significant improvement over baseline speaker-extraction systems.","The evidence is bounded to the recorded EEG/speech setup and tested mixtures; listener attention changes, clinical use, and independent reproduction remain open."),
"chiang25_interspeech":("Reverberation smears speech, and cochlear-implant users are especially affected; a useful enhancer must restore intelligibility, not just make the waveform look cleaner.","Transient speech cues can be blurred by room reflections and by the implant's representation of sound.","Use a fixed convolutional receptive field or optimize only for normal-hearing listeners.","Let deformable convolution move its receptive field to the distortion, and evaluate both signal measures and listeners with cochlear implants.","A deformable-convolution GAN is trained for dereverberation, first tested on REVERB and then assessed in listening tests with normal-hearing and CI users.","The learned offsets change which neighboring time-frequency evidence is combined; intelligibility and quality are judged by objective tests and listener responses.","The paper reports markedly improved CI speech intelligibility by preserving envelope and transient structure.","The claim is bounded to REVERB conditions, the tested listeners, and the GAN configuration; broader hearing profiles, rooms, and independent replication remain open."),
"bagat25_interspeech":("An ASR model should recognize non-native speech across several accents even when each accent has little labeled data and the accent is unknown at test time.","Accent changes sound patterns in different ways, and adapting to one accent can erase performance on others.","Fine-tune one shared model or train a separate full model for every accent.","Keep several small accent-specific adapters and let the system combine them, with or without knowing the accent.","MAS-LoRA attaches low-rank adapters specialized to accents to Whisper and evaluates known- and unknown-accent routing on L2-ARCTIC.","Word error rate measures recognition; comparisons include ordinary LoRA, full fine-tuning, and forgetting after adaptation.","The paper reports lower WER than those baselines, stronger gains when the accent is known, and less catastrophic forgetting.","The result is tied to L2-ARCTIC, its accent set, Whisper, and routing assumptions; spontaneous speech and accents outside the corpus remain open."),
"gong25b_interspeech":("Emotion recognition should work for languages with few labeled examples, not only for languages with large emotion datasets.","Emotion labels are scarce and expressive cues do not transfer unchanged across languages.","Train a supervised classifier only on the small labeled target-language set.","Learn a speech representation without labels using contrastive learning or BYOL, then transfer it across languages.","The study compares self-supervised objectives and analyzes their cross-lingual behavior for Urdu, German, and Bangla emotion recognition.","F1 measures class decisions; the comparison asks how much it improves over supervised or conventional representation learning under limited labels.","The paper reports F1 improvements of 10.6% in Urdu, 15.2% in German, and 13.9% in Bangla.","The reported gains depend on the selected languages, labels, augmentations, and emotion definitions; cultural validity and transfer to new languages remain open."),
"javed25_interspeech":("A deployed ASR system must keep learning as new languages and domains arrive in an uneven real-world stream.","A model can learn the new episode while forgetting older languages, and simulated episodes hide irregular shifts.","Shuffle all data together or evaluate continual learning on artificially regular episodes.","Measure language-incremental, domain-incremental, and joint language-plus-domain learning on naturally arriving speech.","NIRANTAR contains 3,250 hours from 22 languages and 208 Indian districts, with non-uniform episodes and human transcripts; existing continual-learning methods are compared.","The central objects are recognition error over time and retention after each episode; the framework separates language and domain changes instead of averaging them away.","The paper finds that no single evaluated method performs consistently across the three scenarios.","This is a benchmark and comparative study, not proof that one method is universally best; the geography, languages, episode order, and ASR models define the boundary."),
"emezue25_interspeech":("People who speak Igbo, Hausa, or Yoruba need speech technology trained on enough varied speech to work beyond a few speakers.","African languages are underrepresented, and small or homogeneous datasets cannot expose speaker, accent, and recording variation.","Reuse large-resource-language data or build a small dataset without measuring its diversity.","Collect a large, culturally grounded speech-text corpus and test whether it improves several ASR families.","NaijaVoices contains 1,800 hours from more than 5,000 speakers; the paper analyzes acoustic diversity and fine-tunes Whisper, MMS, and XLSR.","Word error rate compares models before and after the new data; corpus scale and speaker diversity are part of the intervention.","The paper reports average WER improvements of 75.86% for Whisper, 52.06% for MMS, and 42.33% for XLSR.","The corpus languages, collection process, transcription policy, and model choices bound the result; coverage of other African languages and deployment conditions remains open."),
"ghosh25_interspeech":("Therapy and feedback need to know where a dysfluency begins and ends, not only whether an entire utterance contains one.","Only weak utterance labels are common, while real dysfluency boundaries are uncertain and synthetic timing is unrealistic.","Classify each utterance or trust every weak label as if it gave exact frame boundaries.","Turn overlapping speech windows into a graph, use a weakly trained classifier to refine links, and reduce its influence when it is uncertain.","StutterCut uses uncertainty-guided normalized cuts and adds frame-level boundaries for four dysfluency types to FluencyBank.","Graph partitioning separates regions; Monte Carlo dropout estimates uncertainty, and F1 plus onset error measure segmentation quality.","The paper reports higher F1 and more precise stuttering-onset detection on real and synthetic data.","The evidence is bounded to FluencyBank, four dysfluency types, annotation quality, and the tested uncertainty model; therapy outcomes and new speakers remain open."),
"fukunaga25_interspeech":("A listener's short responses—such as agreement, continuation, or surprise—help a spoken dialogue feel responsive; a system should choose the right surface form without storing private speaker IDs.","Three broad classes are too coarse for generation, while identity embeddings are difficult to deploy and raise privacy concerns.","Predict a coarse backchannel class from a detailed speaker/listener identity embedding.","Replace identity-specific inputs with general speaker and listener embeddings and predict eleven surface-form categories as well as three classes.","The model uses speech, text, and general embeddings and compares three- and eleven-category prediction against ID-based systems.","Accuracy is reported separately for coarse and fine categories, exposing the cost of richer response choices.","The paper reports 1.3% accuracy improvement for three classes and 0.9% for eleven classes over conventional ID embeddings.","The result is author-reported for the tested dialogue corpus and categories; natural turn timing, privacy leakage in embeddings, and user experience remain open."),
"hu25b_interspeech":("A retrieval system should find the right audio for a long, complicated text request, not only match short captions to short clips.","Audio and text embeddings are trained in different modalities, and simple CLAP-style matching weakens on long or compositional queries.","Use a fixed audio-text contrastive model and rely on its pooled embedding for every query.","Adapt a multimodal language model to produce a universal embedding, using prompts and text-pair training without requiring paired audio in the final training stage.","Vela uses selected prompts and in-context examples, then trains on text pairs; retrieval is tested on ordinary and newly designed long/complex benchmarks.","Text-audio retrieval metrics compare the rank of the correct audio; the new tests ask whether the embedding preserves multiple pieces of a query.","The paper reports that Vela outperforms traditional CLAP models and is more robust on long, complex retrieval tasks.","The abstract says code is forthcoming and the result is tied to the chosen benchmarks and prompts; open-world audio, speech-specific retrieval, and independent reproduction remain open."),
"chandra25_interspeech":("Emotion is ordered: a voice can be more or less excited or positive, but ordinary audio-text contrastive training treats labels as unrelated names.","Ignoring order loses gradual differences and leaves audio and language representations poorly aligned.","Pull each audio sample toward its text label while treating every other label as equally wrong.","Use valence-arousal rankings in a Rank-N-Contrast objective so nearby and distant emotional examples exert different forces.","EmotionRankCLAP aligns emotional speech with natural-language speaking-style prompts and contrasts examples according to their position in valence-arousal space.","The loss encodes an ordering rather than only class identity; cross-modal retrieval tests whether the learned space preserves emotion relations.","The paper reports better emotion ordinality than existing emotion-CLAP systems on cross-modal retrieval.","The result depends on rating dimensions, prompt wording, and the tested emotion corpus; listener disagreement and transfer across cultures remain open."),
"jacquelin25_interspeech":("A speech codec should preserve what was said while allowing a system to change how forcefully it was spoken, such as neutral versus Lombard speech in noise.","Content, speaker identity, and vocal effort are mixed in ordinary representations, so changing effort can damage words or voice quality.","Use one undifferentiated code and hope a conversion model learns effort implicitly.","Place vocal effort in a designated codec layer while keeping semantic content in another layer, making effort controllable.","LombardTokenizer conditions the second quantization layer of SpeechTokenizer on vocal-effort encoders and tests neutral/Lombard conversion and synthesis quality.","Layer-wise discrete codes represent different information; conversion metrics and quality tests compare effort control, intelligibility, and naturalness.","The paper reports better neutral-to-Lombard and Lombard-to-neutral conversion than existing methods while retaining synthesis quality.","The result is tied to the AVID/Lombard data, selected effort conditions, and codec; other speaking styles, languages, and independent listening tests remain open."),
"franzreb25_interspeech":("An anonymizer must hide who is speaking while keeping the words and useful speech intact; a strong attacker may exploit prosody rather than obvious voice quality.","Speaker identity leaks through phone duration and pitch variation even after voice conversion, and a single recognition score does not reveal the leak.","Convert the voice and assume identity is removed once the main spectral cues change.","Add interpretable controls that alter phone duration and pitch variation, then test which changes defeat the speaker-recognition attack.","Private kNN-VC extends kNN voice conversion with duration and variation anonymization and compares target-selection strategies under an attack protocol.","Privacy is measured through attacker recognition error; the interpretable factors connect a score change to a specific speech property.","The paper reports that anonymizing duration and variation substantially increases privacy and that target selection changes attack outcomes.","The evidence is bounded to kNN-VC, the attack model, selected prosodic factors, and utility measures; stronger attackers and human judgments remain open."),
"gourav25_interspeech":("A text-to-speech system should sound natural when a speaker mixes languages in one utterance, as people commonly do in multilingual communities.","Monolingual training assumptions make language switches, pronunciation, and voice continuity brittle.","Force the input into one language or fine-tune on a new code-mixed dataset.","Infer code-mixed speech from multilingual text without requiring additional training data or fine-tuning.","The proposed inference procedure sends multilingual input through an existing TTS system and evaluates generated code-mixed speech with automated MOS-style measures.","The central tradeoff is whether language-switch content is retained while synthesized audio remains natural; the paper uses automated quality scoring rather than a new training loss.","The paper reports an approach for code-mix inference without extra data or fine-tuning; the preserved evidence does not establish broad human preference gains.","The paper's method and evaluation details are bounded by the selected TTS system, languages, and automated metric; human listening, pronunciation accuracy, and unseen language pairs remain open."),
"dumpala25_interspeech":("A depression detector trained in one recording setting should remain useful when test speech comes from another environment, demographic mix, or dataset.","Noise, gender, age, and collection procedures change the speech distribution without changing the clinical question.","Train once on a clean source dataset and assume the test distribution is the same.","Adapt the model at test time using the incoming unlabeled speech so its internal features respond to the new distribution.","The study applies test-time training to a speech-based depression detector and tests shifts from noise, gender, and dataset/curation differences.","Performance under each shift is compared before and after adaptation; the important object is the distribution gap, not only the average source score.","The paper reports substantial performance improvement under the tested shifts.","The task is a clinical screening proxy, not a diagnosis; adaptation stability, labels in deployment, privacy, and external clinical validation remain open."),
"lechler25_interspeech":("Generative speech codecs need listening tests sensitive enough to detect subtle artifacts, but expert MUSHRA studies are expensive and objective metrics can mis-rank new systems.","Crowdsourced listeners vary by platform and expertise, while traditional metrics were designed for older signal distortions.","Use only objective metrics during development or reserve all listening tests for experts at the end.","Adapt MUSHRA for non-experts online, compare platforms with expert data, and test whether objective metrics agree with people.","The paper compares MTurk, Prolific, and expert ratings, measures test-retest reliability, and evaluates six objective metrics on generative speech codecs.","MUSHRA ratings, reliability, platform effects, and metric-to-human alignment are separate quantities; collapsing them into one score hides the evaluation problem.","The paper reports platform-specific bias, reasonable crowdsourced comparisons under its protocol, and that traditional metrics undervalue generative models.","The result is bounded to the codecs, platforms, listener recruitment, and six metrics tested; other populations and model families remain open."),
"baser25b_interspeech":("A deepfake detector should face manipulations that fool people, especially when only a few speech segments are changed to alter meaning.","Many benchmark fakes are easier for humans to spot than real attacks, and scanning every frame wastes computation.","Train on broad synthetic fakes and inspect the whole recording uniformly.","Use language reasoning to choose critical phoneme segments for manipulation, then detect those regions with an adaptive two-level model.","PhonemeFake creates segmental manipulations, measures human and benchmark deception, and trains a detector that allocates computation to suspicious regions across three datasets.","Equal error rate measures detection, localization checks whether manipulated regions are found, and speed measures the cost of adaptive processing.","The paper reports up to 42% lower human perception and 94% lower benchmark accuracy for attacks; its detector reports 91% EER reduction and up to 90% speed-up.","These are author-reported results tied to attack construction, datasets, detector thresholds, and the chosen language reasoning; unseen generators and adversarial adaptation remain open."),
"cumlin25_interspeech":("A speech-quality score should say not only that an utterance is poor but whether noise, coloration, discontinuity, or loudness caused the problem.","A single mean-opinion score hides different defects and cannot express uncertainty or relationships among them.","Predict MOS alone with a point estimator.","Model MOS and four diagnostic quality dimensions jointly as a multivariate probability distribution.","The model predicts a multivariate Gaussian through Cholesky factors and extends probabilistic affine transformations on NISQA ratings.","The mean gives a point estimate, covariance gives uncertainty and correlations, and the NISQA dimensions provide a structured target instead of one scalar.","The paper reports state-of-the-art-level point estimation while uniquely providing uncertainty and cross-dimension correlation estimates.","The result is bounded to NISQA's labels and distributional assumptions; whether listeners and engineers benefit in new codecs or languages remains open."),
"das25b_interspeech":("A person with dysarthria may know what they want to say but be hard to understand; conversion should improve intelligibility without erasing useful content or identity.","Dysarthric speech varies by speaker and severity, and mel-spectrogram targets may make generation slow or blur the relevant units.","Map dysarthric mel features to clean speech with an autoregressive or speaker-specific generator.","Use discrete self-supervised acoustic units and conditional flow matching with a non-autoregressive Diffusion Transformer to map impaired to clearer speech.","The study compares mel-spectrogram and quantized SSL features, controls the output voice with WavLM-derived information, and evaluates generated speech for dysarthric intelligibility.","The learned flow maps a conditioning representation to clean-speech acoustics; intelligibility and convergence compare feature choices and generation paths.","The paper reports that discrete acoustic units improve intelligibility and converge faster than the mel-spectrogram alternative.","The result is bounded to the speakers, severity range, target voice, and tested listening/evaluation protocol; naturalness, identity preservation, and clinical benefit remain open."),
"gu25b_interspeech":("A large speech model must fit on practical hardware without losing recognition quality, especially when storage and memory are tight.","Below eight bits, transformer weight outliers make uniform quantization damage a small number of important parameters.","Round every weight to the same low-precision grid.","Cluster weights nonlinearly, allocate more bits to columns with many outliers, and retain only critical outliers in sparse FP32 form.","The method quantizes Whisper-Large-V3 after training and compares mixed precision and outlier retention across speech datasets.","Bits per parameter expresses storage; WER measures recognition loss, and the columnwise allocation ties precision to the observed weight distribution.","The paper reports 2.12-bit quantization with a 0.17 percentage-point WER increase on LibriSpeech test-clean and under 1% degradation across additional datasets.","The result is author-reported for Whisper-Large-V3 and tested corpora; latency, energy, hardware kernels, and other model families remain open."),
"chen25_interspeech":("A speaker recognizer should recognize a person years later or in a different emotional state, while rejecting unknown people in an open set.","Age and emotion change the same speaker's voice, and limited enrollment data makes it hard to learn every future condition.","Enroll one fixed embedding and set a threshold that assumes the speaker is stable.","Use few-shot foundation-model tuning at enrollment and generate style-rich synthetic speech to expose time-varying and emotional conditions, with losses focused on unknown outliers.","The framework selects synthetic speech, tunes the foundation model with few enrollment examples, and evaluates open-set identification across time-varying and emotional benchmarks.","Identification accuracy and open-set outlier behavior separate recognizing enrolled speakers from rejecting unknown speakers.","The paper reports stronger generalization to aging and emotional variation while maintaining resistance to unknown outliers.","The claim is bounded to the synthetic-data choices, foundation model, enrollment protocol, and benchmarks; real aging trajectories, spoofing attacks, and fairness across groups remain open."),
"blaschke25_interspeech":("An ASR and speech-translation system should preserve what a dialect speaker said rather than silently rewrite dialect grammar into the standard variety.","Dialect differences affect words, grammar, pronunciation, and what counts as a correct transcription; a single standard reference hides these distinctions.","Evaluate one multilingual ASR model against only a standardized transcript.","Create paired dialectal and Standard German references across three underrepresented dialect groups and compare model outputs against both.","Betthupferl contains four hours of read speech from Franconian, Bavarian, and Alemannic speakers plus Standard German; multilingual ASR models are evaluated for transcription and translation.","Error analysis compares similarity to dialectal versus standardized references and inspects grammatical normalization, not only one aggregate score.","The paper reports model-dependent differences: the best system sometimes normalizes dialect grammar but often stays closer to dialect constructions.","The dataset is four hours of read speech from Southeast Germany; spontaneous speech, other dialects, conversational translation, and community judgments remain open."),
}
keys=["bp","wh","naive","ap","mech","math","ww","limits"]
notes=[]; claims=[]; md=["# INTERSPEECH 2025 eighteenth-pass full-paper notes","","Twenty-four additional official-PDF readings deepen the atlas across all 24 conceptual subthemes. Results are author-reported and not independently reproduced.",""]
for i,(pid,vals) in enumerate(N.items(),1):
 if pid not in C: continue
 d=dict(zip(keys,vals)); d.update({"paper_id":pid,"title":P[pid]["title"],"subtheme":C[pid]["subtheme"]}); notes.append(d)
 md += [f"## {i}. {d['subtheme']}","",f"**Paper:** [{d['title']}]({P[pid]['paper_url']})",f"**Evidence:** D3; PDF SHA-256 `{C[pid]['pdf_sha256']}`; full text captured.",""]
 for key,label in zip(keys,["Ordinary problem","Why hard","Naive attempt","Central move","Mechanism","Conceptual structure","What paper reports","Limits"]): md += [f"- **{label}:** {d[key]}"]
 md += [""]; claims.append({"claim_id":f"IS25-D3C18-{i:02d}","paper_id":pid,"subtheme":d["subtheme"],"claim":d["ww"],"evidence_depth":"D3","pdf_sha256":C[pid]["pdf_sha256"],"full_text_sha256":C[pid]["full_text_sha256"],"support_status":"paper-reported-not-independently-verified","independent_support_status":"not-established","limitations":d["limits"]})
(D/"interspeech-2025-eighteenth-d3-notes.json").write_text(json.dumps({"venue":"INTERSPEECH 2025","evidence_depth":"D3","notes":notes},indent=2,ensure_ascii=False)+"\n")
(D/"interspeech-2025-eighteenth-claim-ledger.json").write_text(json.dumps({"venue":"INTERSPEECH 2025","claim_count":len(claims),"claims":claims},indent=2,ensure_ascii=False)+"\n")
R.mkdir(exist_ok=True); (R/"INTERSPEECH_2025_EIGHTEENTH_D3_NOTES.md").write_text("\n".join(md)+"\n")
print(json.dumps({"notes":len(notes),"claims":len(claims)}))
